package main

import (
	"bufio"
	"fmt"
	"os"
	"strconv"
	"strings"
)

type DataReader struct {
	scanner *bufio.Scanner
}

func NewDataReader(r *bufio.Reader) *DataReader {
	scanner := bufio.NewScanner(r)
	scanner.Split(bufio.ScanWords)
	return &DataReader{scanner: scanner}
}

func (dr *DataReader) Next() string {
	dr.scanner.Scan()
	return dr.scanner.Text()
}

func (dr *DataReader) NextInt() int {
	v, _ := strconv.Atoi(dr.Next())
	return v
}

func dfs(u, n, k int, s string, used []bool) bool {
	if u < 0 || u >= n || used[u] || s[u] == '#' {
		return false
	}
	if s[u] == 'T' {
		return true
	}
	used[u] = true
	return dfs(u-k, n, k, s, used) || dfs(u+k, n, k, s, used)
}

func main() {
	var in *bufio.Reader
	var out *bufio.Writer

	if os.Getenv("ONLINE_JUDGE") == "" {
		fIn, _ := os.Open("input.txt")
		fOut, _ := os.Create("output.txt")
		defer fIn.Close()
		defer fOut.Close()
		in = bufio.NewReader(fIn)
		out = bufio.NewWriter(fOut)
	} else {
		in = bufio.NewReader(os.Stdin)
		out = bufio.NewWriter(os.Stdout)
	}
	defer out.Flush()

	dr := NewDataReader(in)
	n := dr.NextInt()
	k := dr.NextInt()
	s := dr.Next()

	used := make([]bool, n)
	start := strings.IndexByte(s, 'G')
	res := dfs(start, n, k, s, used)

	if res {
		fmt.Fprintln(out, "YES")
	} else {
		fmt.Fprintln(out, "NO")
	}
}

